  const unrle = r => r.replace(/(.)~(\d+)~/g, (m, c, n) => c.repeat(+n));
  const PIX = R.BEAST_PIX = {};
  Object.keys(D).forEach(id => {
    const [w, h, pp, rr] = D[id], pal = {}; pp.split(',').forEach(s => { pal[s[0]] = '#' + s.slice(1); });
    const rows = rr.split('|').map(unrle);
    PIX[id] = { w: w + 2, h: h + 2, res: 1, eyes: '',
      pal: () => pal, ol: { '*': ['#16121C', '#16121C'], bare: 'Z' },
      pix: () => rows.map((s, y) => [y + 1, 1, s.replace(/\./g, ' ')]) };
    if (R.BEAST_HD) R.BEAST_HD[id] = PIX[id];
  });
  // 騎腳踏車的人：十種配色用四張圖輪流
  for (let i = 4; i < 10; i++) if (PIX['cyc' + (i % 4)]) { PIX['cyc' + i] = PIX['cyc' + (i % 4)]; if (R.BEAST_HD) R.BEAST_HD['cyc' + i] = PIX['cyc' + i]; }
