  if (R.BEAST_HD) Object.keys(R.BEAST_HD).forEach(id => { const d = R.ENEMIES && R.ENEMIES[id]; if (d && !PIX[id] && !/^領主體/.test(d.name || '')) delete R.BEAST_HD[id]; });
  // 攻擊動作的時機：打到人、射出東西
